pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/17/\",\"title\":\"Chapter Seventeen\",\"has_advanced_view\":true,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":4258,\"bb\":568440,\"url_path\":\"/en/library/bg/16/24/devanagari/\",\"body_final\":\"तस्माच्छास्त्रं प्रमाणं ते कार्याकार्यव्यवस्थितौ ।
ज्ञात्वा शास्त्रविधानोक्तं कर्म कर्तुमिहार्हसि ॥ २४ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":4259,\"bb\":3743,\"url_path\":\"/en/library/bg/16/24/b3743/\",\"body_value\":\"tasmāc chāstraṁ pramāṇaṁ te
kāryākārya-vyavasthitau
jñātvā śāstra-vidhānoktaṁ
karma kartum ihārhasi\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":4260,\"bb\":3744,\"url_path\":\"/en/library/bg/16/24/b3744/\",\"shadow_value\":\"tasmāt – therefore; śāstram – the scriptures; pramāṇam – evidence; te – your; kārya – duty; akārya – and forbidden activities; vyavasthitau – in determining; jñātvā – knowing; śāstra – of scripture; vidhāna – the regulations; uktam – as declared; karma – work; kartum – do; iha – in this world; arhasi – you should.\",\"word_for_word_value\":[{\"word\":\"tasmāt\",\"translation\":\"therefore\"},{\"word\":\"śāstram\",\"translation\":\"the scriptures\"},{\"word\":\"pramāṇam\",\"translation\":\"evidence\"},{\"word\":\"te\",\"translation\":\"your\"},{\"word\":\"kārya\",\"translation\":\"duty\"},{\"word\":\"akārya\",\"translation\":\"and forbidden activities\"},{\"word\":\"vyavasthitau\",\"translation\":\"in determining\"},{\"word\":\"jñātvā\",\"translation\":\"knowing\"},{\"word\":\"śāstra\",\"translation\":\"of scripture\"},{\"word\":\"vidhāna\",\"translation\":\"the regulations\"},{\"word\":\"uktam\",\"translation\":\"as declared\"},{\"word\":\"karma\",\"translation\":\"work\"},{\"word\":\"kartum\",\"translation\":\"do\"},{\"word\":\"iha\",\"translation\":\"in this world\"},{\"word\":\"arhasi\",\"translation\":\"you should\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":4261,\"bb\":3745,\"url_path\":\"/en/library/bg/16/24/b3745/\",\"body_value\":\"One should therefore understand what is duty and what is not duty by the regulations of the scriptures. Knowing such rules and regulations, one should act so that he may gradually be elevated.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4262,\"bb\":3746,\"url_path\":\"/en/library/bg/16/24/b3746/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4263,\"bb\":3747,\"url_path\":\"/en/library/bg/16/24/b3747/\",\"body_value\":\"In India there are many parties of spiritual understanding, generally classified as two: the impersonalist and the personalist. Both of them, however, lead their lives according to the principles of the Vedas. Without following the principles of the scriptures, one cannot elevate himself to the perfectional stage. One who actually, therefore, understands the purport of the śāstras is considered fortunate.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4264,\"bb\":3748,\"url_path\":\"/en/library/bg/16/24/b3748/\",\"body_value\":\"$26\"},{\"type\":\"content.Record\",\"title\":\"paragraph_end\",\"id\":4265,\"bb\":3749,\"url_path\":\"/en/library/bg/16/24/b3749/\",\"body_value\":\"Thus end the Bhaktivedanta Purports to the Sixteenth Chapter of the Śrīmad Bhagavad-gītā in the matter of the Divine and Demoniac Natures.\"}]}],\"short_title\":\"Bg. 16.24\",\"medium_title\":\"Bhagavad-gītā As It Is 16.24\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L27\",\"$L28\",\"$L29\"]}]\n"])self.__next_f.push([1,"2b:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n31:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static